    public record FloorForm(@NotNull @Pattern(regexp = "(\\d{1,13}(\\.\\d{1,2})?)?") String value,
            @Pattern(regexp = FROM) String from) {
    }

    /** The terms as the form submits them: a whole number of days, blank for the default, from a
